/* 2. Base Typography
------------------------------------------------------------------------------*/


a {
    text-decoration: none;
}

/* main container */
#wrapper-menu-aast {
    width: 100%;
    display: flex;
    min-height: 100%;
    position: relative;
    flex-wrap: wrap;
    background-color: #fff;
    justify-content: space-between;
    align-content: space-between;
    -webkit-transform: translateX(0);
    transform: translateX(0);
    transition: -webkit-transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition: transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition: transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55),
        -webkit-transform 800ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
}

.main-container-aasta {
    width: 100%;
}

/* header */
.main-header {
    width: 100%;
    height: auto;
}

h3 {
    font-size: 30px;
}

.header-logo-title h2 {
    color: #1f569b;
    font-size: 1.3em;
    margin-bottom: -2px;
}

span.Logo-txt {
    color: #1f569b;
    font-weight: bold;
    font-size: 13px;
    font-family: var(--ltn__heading-font);
}

/* responsive nav for small devices */

/* hamburger-aasta menu */
.hamburger-aasta {
    padding: 0;
    margin: 0;
    height: 25px;
    width: 25px;
    text-align: center;
    background-color: transparent;
}

.hamburger-aasta:not(.close) {
    position: absolute;
    top: 10px;
    left: 20px;
    /****Eng.mohamed : z-index:999***/
    z-index: 9;
    border: 0;
    display: none;
    width: auto;
    height: auto;
    border: 1px solid #a4a3a3;
    border-radius: 2px;
    /****Eng.mohamed : padding:10px***/
    padding: 5px;
    direction: ltr;
}

.hamburger-aasta:hover,
.hamburger-aasta:focus {
    background-color: transparent;
    outline: none;
}

.hamburger-aasta .line {
    /****Eng.mohamed : width:50px***/
    width: 30px;
    /****Eng.mohamed : height:3px***/
    height: 3px;
    background-color: #3c3c3b;
    display: block;
    /****Eng.mohamed : margin: 10px 0;x***/
    margin: 7px 0;
    transition: all 0.4s ease-in;
    left: 0;
    position: revert;
}

.hamburger-aasta:hover {
    cursor: pointer;
}

.hamburger-aasta.close {
    padding: 10px;
}

.hamburger-aasta.close .wrap {
    position: relative;
    width: 30px;
    height: 30px;
    display: block;
}

.hamburger-aasta.close .line {
    margin: 0;
    width: 100%;
    position: absolute;
    top: calc(50% - 2px);
    transform: rotate(-45deg);
    background-color: #000;
}

.hamburger-aasta.close .line:last-child {
    transform: rotate(45deg);
}

.hamburger-aasta.is-active .line:nth-child(1) {
    transform: rotate(-45deg);
    position: absolute;
    right: 0;
    top: 5px;
}

.hamburger-aasta.is-active .line:nth-child(2) {
    opacity: 0;
    visibility: hidden;
    position: absolute;
    transition: none;
}

.hamburger-aasta.is-active .line:nth-child(3) {
    transform: rotate(45deg);
    position: absolute;
    right: 0;
    top: 5px;
}

#menu-aast {
    position: fixed;
    /****Eng.mohamed : top:0px***/
    top: 145px;
    right: 0;
    bottom: 0;
    width: 100%;
    height: 100%;
    background-color: #f1f1f1;
    max-width: 99%;
    transition: all 0.3s ease-in-out;
    z-index: 999;
    -webkit-transform: translateX(150%);
    transform: translateX(150%);
    transition: -webkit-transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition: transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition: transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55),
        -webkit-transform 500ms cubic-bezier(0.68, -0.55, 0.265, 1.55);
    transition-delay: 0.2s;
    overflow-x: hidden;
    overflow-y: auto;
}

#mobilenav-aast .nav-logo {
    padding: 15px;
}

#mobilenav-aast ul,
#mobilenav-aast li {
    padding: 0;
    margin: 0;
    list-style: none;
    transition: 0;
    position: relative;
}

#mobilenav-aast .caret {
    display: block;
    width: 36px;
    position: absolute;
    top: 1px;
    left: 20px;
    cursor: pointer;
    background-color: #132b61;
}

#mobilenav-aast .caret:not(.trigger-caret) {
    pointer-events: none;
}

#mobilenav-aast .caret:after {
    content: "";
    border: 2px solid #fff;
    border-bottom: 0;
    border-right: 0;
    transform: rotate(-45deg);
    display: block;
    position: absolute;
    height: 15px;
    width: 15px;
    top: 15px;
    left: 8px;
}

#mobilenav-aast ul a {
    display: block;
    padding: 10px 15px;
    cursor: pointer;
    z-index: 2;
    font-size: 16px;
    text-decoration: none;
    color: #fff;
    background: #132b61;
    border-bottom: 1px solid #fff;
    transition: none;
    text-align: right;
}

#mobilenav-aast ul a:hover {
    background: #132b61;
}

#mobilenav-aast .has-sub > a {
    padding-left: 40px;
}

#mobilenav-aast li li a {
    font-size: 14px;
    text-decoration: none;
    color: #dddddd;
    background: #132b61;
}

#mobilenav-aast .nav-backdrop {
    position: fixed;
    height: 100%;
    width: 100%;
    background: rgba(0, 0, 0, 0.8);
    z-index: -1;
    opacity: 0;
    visibility: hidden;
    transition: all 0.5s ease-in;
}

#mobilenav-aast .menu-outer {
    padding-bottom: 60px;
    overflow: hidden;
    overflow-y: auto;
    /* box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px; */
    max-height: 100%;
}

