/* drop-down */
.nav-aast ul li ul {
    position: absolute;
    top: calc(100%);
    right: 0;
    margin: 0;
    width: 200px;
    z-index: 4;
    opacity: 0;
    pointer-events: none;
    visibility: hidden;
    transition: 0.3s;
    box-shadow: rgba(0, 0, 0, 0.24) 0px 3px 8px;
    min-width: 260px;
}

.nav-aast ul li ul li {
